'use client';
import {flushSync} from 'react-dom';
import {reservationStatus} from '@/lib/reservation-status';
import {PaymentActivityReport} from '@/components/payment-activity-report';
import {useEffect,useRef,useState} from 'react';
import {hotelRpc} from '@/lib/pilot';
import {afterDays} from '@/lib/rates';
import {downloadReport,reportMoney,type ReportCell} from '@/lib/report-export';
import {validateBillingBalanceReport,activityMeasures,activityHeaders,activityRows,balanceMeasures,balanceHeaders,balanceRows,balanceBasis,folioMoney,type ActivityReport,type BalanceReport} from '@/lib/folio-reports';
type Props={tenant:string;property:string;businessDate:string;actor?:string;disabled?:boolean;reviewRevision?:number;onReview?:(reservation:string,entry:string)=>void};type Kind='activity'|'balances';type Selection=Kind|'payment_activity';
export function FolioReports(props:Props){const [kind,setKind]=useState<Selection>('activity');return <><label className="field pilot-report-kind">Folio report<select value={kind} disabled={props.disabled} onChange={e=>setKind(e.target.value as Selection)}><option value="activity">Recorded folio activity</option><option value="balances">Current guest balances</option>{props.actor&&props.onReview&&<option value="payment_activity">Recorded payment activity</option>}</select></label>{kind==='payment_activity'?props.actor&&props.onReview&&<PaymentActivityReport actor={props.actor} tenant={props.tenant} property={props.property} businessDate={props.businessDate} disabled={props.disabled} reviewRevision={props.reviewRevision} onOpen={props.onReview}/>:<FolioReport key={props.tenant+'/'+props.property+'/'+kind} {...props} kind={kind}/>}</>}
function ReportTable({headers,rows,caption}:{headers:string[];rows:ReportCell[][];caption:string}){
 const [page,setPage]=useState(0),[printing,setPrinting]=useState(false);const size=50,index=Math.min(page,Math.max(0,Math.ceil(rows.length/size)-1));
 useEffect(()=>{setPage(0)},[rows]);
 useEffect(()=>{const before=()=>flushSync(()=>setPrinting(true)),after=()=>setPrinting(false);window.addEventListener('beforeprint',before);window.addEventListener('afterprint',after);return()=>{window.removeEventListener('beforeprint',before);window.removeEventListener('afterprint',after)}},[]);
 const visible=printing?rows:rows.slice(index*size,(index+1)*size);
 return <><div className="pilot-table-wrap"><table className="pilot-table"><caption>{caption}</caption><thead><tr>{headers.map(h=><th scope="col" key={h}>{h}</th>)}</tr></thead><tbody>{visible.map((row,i)=><tr key={index*size+i}>{row.map((cell,j)=><td key={j} data-label={headers[j]}>{cell==null||cell===''?'—':String(cell)}</td>)}</tr>)}</tbody></table>{!rows.length&&<p className="pilot-empty">No records in this snapshot.</p>}</div>{!printing&&rows.length>size&&<nav className="pilot-actions" aria-label={'Pages: '+caption}><button className="secondary" aria-label={'Previous rows: '+caption} disabled={index===0} onClick={()=>setPage(index-1)}>Previous</button><span>Rows {index*size+1}–{Math.min((index+1)*size,rows.length)} of {rows.length}. CSV includes all rows.</span><button className="secondary" aria-label={'Next rows: '+caption} disabled={(index+1)*size>=rows.length} onClick={()=>setPage(index+1)}>Next</button></nav>}</>;
}

function FolioReport({tenant,property,businessDate,kind}:Props&{kind:Kind}){
 const detail=useRef<HTMLDetailsElement>(null);
 useEffect(()=>{let wasOpen:boolean|null=null;const before=()=>{if(detail.current&&wasOpen===null){wasOpen=detail.current.open;detail.current.open=true}},after=()=>{if(detail.current&&wasOpen!==null)detail.current.open=wasOpen;wasOpen=null};window.addEventListener('beforeprint',before);window.addEventListener('afterprint',after);return()=>{window.removeEventListener('beforeprint',before);window.removeEventListener('afterprint',after);after()}},[]);
 const [initialStart]=useState(afterDays(businessDate,-6)),[initialEnd]=useState(afterDays(businessDate,1)),[start,setStart]=useState(initialStart),[end,setEnd]=useState(initialEnd),[data,setData]=useState<ActivityReport|BalanceReport|null>(null),[loaded,setLoaded]=useState(''),[busy,setBusy]=useState(true),[error,setError]=useState('');const alive=useRef(true),sequence=useRef(0);
 const scope=tenant+'/'+property+'/'+kind,key=scope+(kind==='activity'?'/'+start+'/'+end:'');
 const args=(from:string,until:string)=>kind==='activity'?{p_tenant:tenant,p_property:property,p_start:from,p_end:until}:{p_tenant:tenant,p_property:property};const rpc=kind==='activity'?'folio_activity_report':'billing_current_balances';
 async function load(){const seq=++sequence.current;setBusy(true);setLoaded('');setError('');try{if(kind==='activity'&&(!start||!end||end<=start))throw Error('Choose a recording period with an end date after the start.');const result=await hotelRpc<ActivityReport|BalanceReport>(rpc,args(start,end));if(kind==='balances')validateBillingBalanceReport(result,tenant,property);if(alive.current&&sequence.current===seq){setData(result);setLoaded(key)}}catch(e){if(alive.current&&sequence.current===seq)setError(e instanceof Error?e.message:'Unable to load the financial report.')}finally{if(alive.current&&sequence.current===seq)setBusy(false)}}
 useEffect(()=>{alive.current=true;const seq=++sequence.current;hotelRpc<ActivityReport|BalanceReport>(kind==='activity'?'folio_activity_report':'billing_current_balances',kind==='activity'?{p_tenant:tenant,p_property:property,p_start:initialStart,p_end:initialEnd}:{p_tenant:tenant,p_property:property}).then(result=>{if(kind==='balances')validateBillingBalanceReport(result,tenant,property);if(alive.current&&sequence.current===seq){setData(result);setLoaded(tenant+'/'+property+'/'+kind+(kind==='activity'?'/'+initialStart+'/'+initialEnd:''));setError('')}}).catch(e=>{if(alive.current&&sequence.current===seq)setError(e instanceof Error?e.message:'Unable to load the financial report.')}).finally(()=>{if(alive.current&&sequence.current===seq)setBusy(false)});return()=>{alive.current=false}},[tenant,property,kind,initialStart,initialEnd]);
 const fresh=!!data&&loaded===key&&!busy&&!error,a=fresh&&kind==='activity'?data as ActivityReport:null,b=fresh&&kind==='balances'?data as BalanceReport:null,title=kind==='activity'?'Recorded folio activity':'Current guest balances';
 function exportCsv(){if(!fresh||!data)return;try{const rows:ReportCell[][]=[['iRatePilot PMS',title],['Property',data.property.name],['Time zone',data.property.time_zone],['Currency','USD'],['Payment basis','External records only; no processor capture, settlement, collected cash or full accounts receivable is implied.'],...Object.entries(data.definitions).map(([k,v])=>[k,v])];if(a)rows.push(['Recording period start',a.period.start],['Recording period end (exclusive)',a.period.end],['Timestamp boundary start',a.period.start_at],['Timestamp boundary end',a.period.end_at],['Generated at',a.generated_at],['Entry count',a.totals.entry_count],...activityMeasures.map(([k,label])=>[label+' USD',reportMoney(a.totals[k])]),[],activityHeaders,...activityRows(a));if(b)rows.push(['Snapshot as of',b.as_of],['Operational calendar date',b.business_date],['Scope','All property reservations, all statuses and stay dates. No historical balance or age calculation.'],['Completeness',b.totals.complete?'All amounts available':'Known subtotals only; unavailable rows excluded from monetary totals'],['Reservations',b.totals.reservation_count],['Unavailable amounts',b.totals.unavailable_count],['Positive balances',b.totals.positive_balance_count],['Credit balances',b.totals.credit_balance_count],['Zero balances',b.totals.zero_balance_count],['Reservation differs from opening',b.totals.changed_reservation_count],['Pricing review required',b.totals.pricing_review_count],...balanceMeasures.map(([k,label])=>[label+' USD',reportMoney(b.totals[k])]),[],balanceHeaders,...balanceRows(b));downloadReport(data.property.name+'-folio-'+kind+'-'+(a?.period.start??b?.business_date),rows)}catch(e){setError(e instanceof Error?e.message:'Unable to export the report.')}}
 return <section className="card pilot-reports"><div className="pilot-report-controls"><div className="section-top"><div><h2>{title}</h2><p>{kind==='activity'?'Entries recorded during a local calendar period.':'All property reservations at the current snapshot, including future and cancelled stays.'}</p></div><div className="pilot-actions"><button className="secondary" disabled={!fresh} onClick={exportCsv}>Export folio report CSV</button><button className="secondary" disabled={!fresh} onClick={()=>window.print()}>Print folio report / PDF</button></div></div><form className="pilot-report-filters" onSubmit={e=>{e.preventDefault();void load()}}>{kind==='activity'&&<><label className="field">Recording date from<input type="date" required value={start} disabled={busy} onChange={e=>setStart(e.target.value)}/></label><label className="field">Recording date until (exclusive)<input type="date" required value={end} disabled={busy} onChange={e=>setEnd(e.target.value)}/></label></>}<button className="primary" disabled={busy}>{busy?'Loading…':kind==='activity'?'Load recorded activity':'Refresh current balances'}</button></form>{error&&<div className="pilot-error" role="alert">{error}</div>}</div>{!fresh?<output className="pilot-empty">{busy?'Loading the requested snapshot…':'Load the selected scope before viewing or exporting.'}</output>:data&&<div className="pilot-report-print"><div className="pilot-report-heading"><span className="pilot-eyebrow">{data.property.name}</span><h2>{title}</h2><p>{a?a.period.start+' through '+a.period.end+' (end exclusive)':'All statuses and stay dates'} · {data.property.time_zone}</p><small>Snapshot {a?.generated_at??b?.as_of}</small></div><p className="pilot-report-basis">Payment amounts are externally recorded evidence. These reports do not establish collected cash, processor capture, settlement, earned revenue or overdue receivables.</p>{a&&<><p>Dates use the time each immutable entry was recorded in this property’s current time zone. Stay dates, external transaction dates and settlement dates are separate. Source and status labels are current. Opening stay charges are excluded from this activity report.</p><p>{a.totals.entry_count} recorded entries.</p><div className="pilot-report-totals">{activityMeasures.map(([k,label])=><div key={k}><span>{label}</span><strong>{folioMoney(a.totals[k])}</strong></div>)}</div><ReportTable headers={activityHeaders} rows={activityRows(a)} caption="Recorded folio activity in USD"/><p>Payment record reductions correct an earlier entry; they do not represent an external refund.</p></>}{b&&<>{!b.totals.complete&&<div className="pilot-error" role="alert">{b.totals.unavailable_count} reservations have unavailable amounts. Monetary figures are known subtotals only. Unknown records are not counted as zero balances.</div>}<p>{b.totals.reservation_count} reservations · {b.totals.available_count} available · {b.totals.unavailable_count} unknown · {b.totals.positive_balance_count} positive · {b.totals.credit_balance_count} credit · {b.totals.zero_balance_count} zero balances.</p><p>{b.totals.changed_reservation_count} reservations differ from their frozen opening · {b.totals.pricing_review_count} need pricing review.</p><div className="pilot-report-totals">{balanceMeasures.map(([k,label])=><div key={k}><span>{label}</span><strong>{folioMoney(b.totals[k])}</strong></div>)}</div><p>A positive amount is a recorded charge balance, including possible future stay value; it is not automatically overdue or collectible. A signed negative credit is not approval to refund. Frozen openings remain the basis when reservation pricing changes.</p><ReportTable headers={['Reservation / source reference','Current status','Stay','Amount basis','Charges USD','Net recorded paid USD','Original balance USD','Transferred USD','Guest balance USD','Review']} rows={b.rows.map(r=>[r.source_booking_id+' / '+r.reservation_id,reservationStatus(r),(r.arrival??'Unknown')+' to '+(r.departure??'Unknown'),balanceBasis(r.opening_mode),r.totals?reportMoney(r.totals.charges_minor):'Unknown',r.totals?reportMoney(r.totals.recorded_paid_minor):'Unknown',r.totals?reportMoney(r.totals.original_balance_minor):'Unknown',r.totals?reportMoney(r.totals.routed_charge_minor):'Unknown',r.totals?reportMoney(r.totals.balance_minor):'Unknown',[!r.available?'Amounts unavailable':null,r.reservation_amounts_changed?'Reservation differs from opening':null,r.pricing_reconciliation_required?'Pricing review required':null].filter(Boolean).join('; ')])} caption="Current balances across every stay date"/><details ref={detail} className="pilot-balance-detail"><summary>View full opening and recorded-entry breakdown</summary><ReportTable headers={balanceHeaders} rows={balanceRows(b)} caption="Full current balance basis in USD"/></details></>}<output className="pilot-report-footnote">Read-only snapshot. Refresh after recording folio entries. Exports include scope, definitions and full amount details.</output></div>}</section>;
}
